-- Rifts World Book 34: Northern Gun Two, the separately priced Midas blade, Night Reaper thigh UEL, Prophet blade plating and Pit Fighter options (printed 123-132)
-- 20 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~310-northern-gun-2-power-armor-f-gear.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('ng-x16-midas-giant-vibro-blade', 'Midas Giant Vibro-Blade Pole Arm', 'rifts', 'weapon', 100, 215000, '215,000 credits sold on its own; standard with the Midas power armor.', '4D6 M.D. with the blade of the halberd or battle axe, 2D6 M.D. with the blunt end, at the Midas''s Robot P.S. 30', 1, 'Melee; halberd 12 ft (3.6 m) reach, battle axe 8 ft (2.4 m)', 'Unlimited', 'Equal to the wielder''s combined hand to hand attacks', NULL, NULL, NULL, 'The Midas power armor''s oversized halberd or battle axe, its edges and tip working as huge Vibro-Blades powered through energy connectors in the wielder''s hands, and silver plated against the supernatural. Made for the Midas but also bought by Combat Cyborgs, large D-Bees and owners of other power armor. +1 to parry and disarm. About 100 lbs (45 kg).', 'Rifts World Book 34: Northern Gun Two p.123-125', NULL),
  ('ng-uelx45-thigh-uel', 'Extra Thigh UEL (Night Reaper upgrade)', 'rifts', 'gear', NULL, 160000, '160,000 credits on top of the Night Reaper power armor''s price.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'An extra or emergency Universal Energy Link built into one thigh of the Night Reaper light power armor, beside the standard pair in its forearms: an E-Clip connector on a thin cable that powers a handheld energy weapon of up to 1D6x10 M.D. a blast, its breaker shutting off anything stronger.', 'Rifts World Book 34: Northern Gun Two p.127', NULL),
  ('ng-x67-prophet-silver-plating', 'Silver Plating (Prophet Vibro-Blade upgrade)', 'rifts', 'gear', NULL, 2500, '2,500 credits per blade, for either of the Prophet power armor''s two forearm Vibro-Blades.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'An optional silver plating for one of the concealed forearm Vibro-Blades of the Prophet power armor, for fighting supernatural enemies.', 'Rifts World Book 34: Northern Gun Two p.132', NULL),
  ('ng-gccpa-03-leg-jump-jets', 'Leg Jump Jets (Pit Fighter option)', 'rifts', 'gear', NULL, 80000, '80,000 credits as an option for the Pit Fighter power armor.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Jump jets built into both legs of the Pit Fighter gladiator power armor, lifting its leaps to as much as 50 ft (15.2 m) high or across, +20% with a running start.', 'Rifts World Book 34: Northern Gun Two p.128', NULL),
  ('ng-gccpa-03-fire-breath-plasma-cannon', 'Fire Breath Plasma Cannon (Pit Fighter option)', 'rifts', 'weapon', NULL, 30000, '30,000 credits as an option for the Pit Fighter power armor.', '4D6 M.D. per blast as throttled; 1D4x10 M.D. with the nozzle tightened, losing the fire-breath look', 1, '120 ft (36.6 m) on the helmet; triple on a forearm, same damage', 'Effectively unlimited', 'Single shot; each blast counts as one melee attack', NULL, NULL, NULL, 'A light plasma cannon for the Pit Fighter''s helmet, hidden at the chin or along the jaw, or for a forearm. It is opened up on purpose so the plasma spills out in a weak spray that looks like a monster breathing fire. Anti-armor, anti-robot and anti-monster, secondarily assault.', 'Rifts World Book 34: Northern Gun Two p.129', NULL),
  ('ng-gccpa-03-eye-lasers', 'Eye Lasers (Pit Fighter option)', 'rifts', 'weapon', NULL, 15000, '15,000 credits as an option for the Pit Fighter power armor.', '1D6 M.D. per single blast; 2D6 M.D. with both eyes at one target', 1, '400 ft (122 m)', 'Effectively unlimited', 'Each single or linked blast counts as one melee attack', NULL, NULL, NULL, 'A pair of simple light lasers set in the eyes of the Pit Fighter''s helmet as backup weapons. Assault and defense, secondarily anti-personnel.', 'Rifts World Book 34: Northern Gun Two p.129', NULL),
  ('ng-gccpa-03-laser-forearm-blaster', 'Laser Forearm Blaster (Pit Fighter option)', 'rifts', 'weapon', NULL, 28000, '28,000 credits as an option for the Pit Fighter power armor.', '3D6 M.D. per blast', 1, '1,000 ft (305 m)', 'Effectively unlimited', 'Each blast counts as one melee attack', NULL, NULL, NULL, 'A point-and-fire laser blaster built onto one forearm of the Pit Fighter gladiator power armor. Assault and defense, secondarily anti-personnel.', 'Rifts World Book 34: Northern Gun Two p.129', NULL),
  ('ng-gccpa-03-ion-forearm-blaster', 'Ion Forearm Blaster (Pit Fighter option)', 'rifts', 'weapon', NULL, 32000, '32,000 credits as an option for the Pit Fighter power armor.', '4D6 M.D. per blast', 1, '600 ft (183 m)', 'Effectively unlimited', 'Each blast counts as one melee attack', NULL, NULL, NULL, 'A point-and-fire ion blaster built onto one forearm of the Pit Fighter gladiator power armor. Assault and defense, secondarily anti-personnel.', 'Rifts World Book 34: Northern Gun Two p.129', NULL),
  ('ng-gccpa-03-plasma-forearm-blaster', 'Plasma Forearm Blaster (Pit Fighter option)', 'rifts', 'weapon', NULL, 40000, '40,000 credits as an option for the Pit Fighter power armor.', '4D6 M.D. per blast', 1, '600 ft (183 m)', 'Effectively unlimited', 'Each blast counts as one melee attack', NULL, NULL, NULL, 'A point-and-fire plasma blaster built onto one forearm of the Pit Fighter gladiator power armor. Assault and defense, secondarily anti-personnel.', 'Rifts World Book 34: Northern Gun Two p.129', NULL),
  ('ng-gccpa-03-forearm-grenade-launcher', 'Forearm Grenade Launcher (Pit Fighter option)', 'rifts', 'weapon', NULL, 35000, '35,000 credits as an option for the Pit Fighter power armor.', 'By grenade type; high explosive and plasma make the best show in the arena', 1, '400 ft (122 m)', 'Four grenades', 'Single shot; each grenade counts as one melee attack', NULL, NULL, NULL, 'A point-and-fire grenade launcher built onto one forearm of the Pit Fighter gladiator power armor. Assault and defense, secondarily anti-personnel.', 'Rifts World Book 34: Northern Gun Two p.129', NULL),
  ('ng-gccpa-03-forearm-grappling-hook', 'Forearm Grappling Hook (Pit Fighter option)', 'rifts', 'weapon', NULL, 12000, '12,000 credits as an option for the Pit Fighter power armor.', '1 M.D. when the hook or spike is fired into something; it must be pulled free to use again', 1, '30 ft (9.1 m)', '48 ft (14.6 m) of cable, enough for 4-8 attacks', 'Each use counts as one melee attack', NULL, NULL, NULL, 'A grappling hook launcher on one forearm of the Pit Fighter, for climbing, swinging around walls and obstacles and snaring foes; the hook can instead be let out on 6-12 ft (1.8 to 3.7 m) of line to trip legs or tangle a limb. +1 to entangle and trip with it. A favorite with arena crowds. Assault and defense, secondarily anti-personnel.', 'Rifts World Book 34: Northern Gun Two p.129', NULL),
  ('ng-gccpa-03-forearm-vibro-short-sword', 'Forearm Vibro-Short Sword (Pit Fighter option)', 'rifts', 'weapon', NULL, 10000, '10,000 credits as an option for the Pit Fighter power armor.', '2D4 M.D.', 1, 'Melee only; arm''s reach plus 1-2 ft (0.3 to 0.6 m) of blade', NULL, 'Equal to the pilot''s combined hand to hand attacks', NULL, NULL, NULL, 'A retractable Vibro-Short Sword built into one forearm of the Pit Fighter gladiator power armor for melee. Assault, secondarily defense.', 'Rifts World Book 34: Northern Gun Two p.129-130', NULL),
  ('ng-gccpa-03-forearm-vibro-claws', 'Forearm Vibro-Claws (Pit Fighter option)', 'rifts', 'weapon', NULL, 12000, '12,000 credits as an option for the Pit Fighter power armor.', '2D4+3 M.D.', 1, 'Melee only; arm''s reach', NULL, 'Equal to the pilot''s combined hand to hand attacks', NULL, NULL, NULL, 'Three curved claws, or three long narrow blades, that extend and retract from one forearm of the Pit Fighter gladiator power armor. Assault, secondarily defense.', 'Rifts World Book 34: Northern Gun Two p.130', NULL),
  ('ng-gccpa-03-vibro-spikes-or-blades', 'Vibro-Spikes or Blades, per set (Pit Fighter option)', 'rifts', 'weapon', NULL, 10000, '10,000 credits per set as an option for the Pit Fighter power armor; each location needs its own set.', '1D6 M.D. for a set of four small Vibro-Spikes; 2D4 M.D. for a set of two dagger-size blades or bigger spikes', 1, 'Melee only', NULL, 'Equal to the pilot''s combined hand to hand attacks', NULL, NULL, NULL, 'A set of four Vibro-Spikes or two Vibro-Blades for one spot on the Pit Fighter: a shin, knee, heel, forearm back, elbow or shoulder top, there to look fearsome or to ram and impale. Assault, secondarily defense.', 'Rifts World Book 34: Northern Gun Two p.130', NULL),
  ('ng-gccpa-03-whipping-cables', 'Whipping Cables (Pit Fighter option)', 'rifts', 'weapon', NULL, 6500, '6,500 credits for the standard pair as an option for the Pit Fighter power armor; the energized pair is 12,500 (ng-gccpa-03-energized-whipping-cables).', '1D4 M.D. per lash, or entangle and tie up the opponent', 1, 'Melee only; 15 ft (4.6 m) long', NULL, 'Equal to the pilot''s combined hand to hand attacks', NULL, NULL, NULL, 'A pair of cables that lash out from housings under the Pit Fighter''s forearms. +1 to strike, +1 to disarm and +2 to entangle with them. Anti-personnel, secondarily defense.', 'Rifts World Book 34: Northern Gun Two p.130', NULL),
  ('ng-gccpa-03-energized-whipping-cables', 'Energized Whipping Cables (Pit Fighter option)', 'rifts', 'weapon', NULL, 12500, '12,500 credits for the energized pair as an option for the Pit Fighter power armor.', '1D6+2 M.D. per lash, sparking at each hit, or entangle and tie up the opponent', 1, 'Melee only; 15 ft (4.6 m) long', NULL, 'Equal to the pilot''s combined hand to hand attacks', NULL, NULL, NULL, 'The electrified version of the Pit Fighter''s paired forearm whipping cables, throwing sparks with every hit. +1 to strike, +1 to disarm and +2 to entangle with them. Anti-personnel, secondarily defense.', 'Rifts World Book 34: Northern Gun Two p.130', NULL),
  ('ng-gccpa-03-shoulder-net-launcher', 'Concealed Shoulder Net Launcher (Pit Fighter option)', 'rifts', 'weapon', NULL, 27000, '27,000 credits as a shoulder mount for the Pit Fighter power armor; the handheld version is 32,000 and replacement nets 3,500 each.', 'None; immobilizes. A caught victim is down to one melee action per round until 3D6+20 M.D. is done to the netting; fire does double and burns the net away in one round, burning the victim too', 0, '100 ft (30.5 m)', '4 nets', 'Each net counts as one melee attack', NULL, NULL, NULL, 'A hidden shoulder launcher firing a bundle of glue-coated M.D.C. mesh that bursts open in flight; weighted cords wrap the target and stick to each other. A successful dodge avoids it. It holds Robot P.S. 24 (Supernatural 18) or less; stronger foes tear free in 1D4 melee actions, and above Robot P.S. 32 (Supernatural 24) in one. Cutting free from inside takes 1D4+1 melee actions besides the damage, and a net round the lower legs needs 3 more P.S. to break. Used in the arena to slow a foe for the kill, to taunt one, or to deal with another. Capture, secondarily anti-personnel and defense.', 'Rifts World Book 34: Northern Gun Two p.130', NULL),
  ('ng-gccpa-03-handheld-net-launcher', 'Handheld Net Launch Rifle (Pit Fighter option)', 'rifts', 'weapon', NULL, 32000, '32,000 credits; the shoulder-mounted version is 27,000 and replacement nets 3,500 each.', 'None; immobilizes. A caught victim is down to one melee action per round until 3D6+20 M.D. is done to the netting; fire does double and burns the net away in one round, burning the victim too', 0, '100 ft (30.5 m)', '4 nets', 'Each net counts as one melee attack', NULL, NULL, NULL, 'The bazooka-like handheld form of the Pit Fighter''s net launcher, firing the same glue-coated M.D.C. nets that hold Robot P.S. 24 (Supernatural 18) or less. Capture, secondarily anti-personnel and defense.', 'Rifts World Book 34: Northern Gun Two p.130', NULL),
  ('ng-gccpa-03-replacement-net', 'Replacement Net (Pit Fighter net launcher)', 'rifts', 'gear', NULL, 3500, '3,500 credits each.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'One reload for the Pit Fighter''s shoulder or handheld net launcher: a bundled, glue-coated M.D.C. mesh net with weighted cords, taking 3D6+20 M.D. to cut and burning away quickly in M.D. fire.', 'Rifts World Book 34: Northern Gun Two p.130', NULL),
  ('ng-gccpa-03-vibro-chainsaw-sword', 'Giant Two-Handed Vibro-Chainsaw Sword (Pit Fighter option)', 'rifts', 'weapon', 50, 55000, '55,000 credits.', '5D6+5 M.D. per strike', 1, 'Melee; 5 ft (1.5 m) beyond arm''s reach, 7 ft (2.1 m) overall', '30 minutes per E-Clip in the hilt; unlimited on a UEL', 'Equal to the wielder''s combined hand to hand attacks', NULL, NULL, NULL, 'A huge chainsaw sword first made for Combat Cyborgs and loved by arena crowds: a 5 ft (1.5 m) Vibro-Chainsaw blade on a long 2 ft (0.6 m) handle for two hands. +1 to parry and disarm. Needs Robot P.S. 19 two-handed and 25 one-handed; weaker users are -5 to strike and parry, and below Robot P.S. 16 -10 to strike, parry and disarm. Assault, secondarily anti-armor, anti-robot and anti-monster. 50 lbs (22.5 kg).', 'Rifts World Book 34: Northern Gun Two p.130', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 20 gear rows are in' AS assertion, count(*) AS got, 20 AS want
  FROM gear WHERE slug IN ('ng-x16-midas-giant-vibro-blade', 'ng-uelx45-thigh-uel', 'ng-x67-prophet-silver-plating', 'ng-gccpa-03-leg-jump-jets', 'ng-gccpa-03-fire-breath-plasma-cannon', 'ng-gccpa-03-eye-lasers', 'ng-gccpa-03-laser-forearm-blaster', 'ng-gccpa-03-ion-forearm-blaster', 'ng-gccpa-03-plasma-forearm-blaster', 'ng-gccpa-03-forearm-grenade-launcher', 'ng-gccpa-03-forearm-grappling-hook', 'ng-gccpa-03-forearm-vibro-short-sword', 'ng-gccpa-03-forearm-vibro-claws', 'ng-gccpa-03-vibro-spikes-or-blades', 'ng-gccpa-03-whipping-cables', 'ng-gccpa-03-energized-whipping-cables', 'ng-gccpa-03-shoulder-net-launcher', 'ng-gccpa-03-handheld-net-launcher', 'ng-gccpa-03-replacement-net', 'ng-gccpa-03-vibro-chainsaw-sword') AND source_book IS NOT NULL;

